#!/bin/bash
set -e

echo "=== Aggiorno le copertine reali dei libri ==="

mkdir -p public/covers

base64 -d > public/covers/feeder.jpg << 'FEEDEREOF'

FEEDEREOF

base64 -d > public/covers/mare-e-foce.jpg << 'MAREEOF'

MAREEOF

echo "=== Copertine salvate: ==="
echo "  public/covers/feeder.jpg"
echo "  public/covers/mare-e-foce.jpg"
echo ""
echo "Ricorda: bash aggiorna-copertine.sh, poi:"
echo "git add -A && git commit -m 'aggiorna copertine reali feeder e mare-e-foce' && git push"
